import backtrader as bt


class MonthlySeasonalityStrategy(bt.Strategy):
    def __init__(self):
        self.order = []
        self.monthly_returns = {month: [] for month in range(1, 13)}
        self.current_month = None
        self.month_first_open = None
        self.month_last_close = None
        self.entry_price = None
        self.stopped_for_month = False

    def notify_order(self, order):
        if order.status in (
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ):
            if order in self.order:
                self.order.remove(order)
            if order.status == order.Completed:
                role = order.info.get("role")
                if role == "entry":
                    self.entry_price = order.executed.price
                elif role in ("exit", "stop") and not self.position:
                    self.entry_price = None

    def _submit(self, order, role):
        order.addinfo(role=role)
        self.order.append(order)

    def _set_monthly_target(self, bias):
        if bias == 0:
            if self.position:
                self._submit(self.close(), "exit")
            return

        if bias > 0:
            if self.position.size < 0:
                self._submit(self.close(), "exit")
                self._submit(self.buy(), "entry")
            elif not self.position:
                self._submit(self.buy(), "entry")
        else:
            if self.position.size > 0:
                self._submit(self.close(), "exit")
                self._submit(self.sell(), "entry")
            elif not self.position:
                self._submit(self.sell(), "entry")

    def next(self):
        dt = self.data.datetime.datetime(0)
        month_key = (dt.year, dt.month)

        if month_key != self.current_month:
            if self.current_month is not None:
                completed_return = (
                    self.month_last_close / self.month_first_open
                ) - 1.0
                self.monthly_returns[self.current_month[1]].append(completed_return)

            self.current_month = month_key
            self.month_first_open = self.data.open[0]
            self.month_last_close = self.data.close[0]
            self.stopped_for_month = False

            history = self.monthly_returns[dt.month]
            if len(history) < 1:
                bias = 0
            else:
                average_return = sum(history) / len(history)
                if average_return > 0:
                    bias = 1
                elif average_return < 0:
                    bias = -1
                else:
                    bias = 0

            if not self.order:
                self._set_monthly_target(bias)
            return

        self.month_last_close = self.data.close[0]

        if self.order or self.stopped_for_month or not self.position:
            return

        if self.position.size > 0 and self.data.low[0] <= self.entry_price * 0.98:
            self._submit(self.close(), "stop")
            self.stopped_for_month = True
        elif self.position.size < 0 and self.data.high[0] >= self.entry_price * 1.02:
            self._submit(self.close(), "stop")
            self.stopped_for_month = True
